#!/usr/bin/env python3
import base64
import json
import subprocess
import sys
from pathlib import Path

OWNER = 'ibb142'
REPO = 'ivx-holdings-platform'
TOKEN = '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'
BRANCH = 'main'

FILES = [
    'expo/lib/auth-context.tsx',
    'expo/__tests__/auth-timeout-fix.test.ts',
    'expo/android/app/build.gradle',
]

COMMIT_MESSAGE = 'fix(owner-login): Instagram technique — mobile never calls Supabase Auth directly\n\nThe mobile network path to Supabase Auth intermittently returns HTTP 504.\nInstead, the app now sends credentials to POST /api/members/login on the\nIVX backend, which authenticates server-side and returns real JWT tokens.\nThe mobile app installs the session via setSession(), the same pattern\nused by passwordless owner login.\n\n- Replace direct signInWithEmailPassword in auth-context.tsx login callback\n- Extend /api/members/login timeout to 45s (auth endpoint)\n- Bump APK to v1.10.1 / versionCode 99\n- Add regression tests for Instagram backend-login flow'

def gh_api(method, path, data=None, extra_headers=None):
    url = f'https://api.github.com/{path}'
    headers = {
        'Accept': 'application/vnd.github+json',
        'Authorization': f'Bearer {TOKEN}',
        'X-GitHub-Api-Version': '2022-11-28',
    }
    if extra_headers:
        headers.update(extra_headers)
    cmd = ['curl', '-sS', '-X', method, url]
    for k, v in headers.items():
        cmd += ['-H', f'{k}: {v}']
    if data is not None:
        if isinstance(data, str):
            cmd += ['--data-binary', data]
        elif isinstance(data, bytes):
            # write to temp file and use @path
            raise RuntimeError('use temp file for binary data')
        else:
            cmd += ['-d', json.dumps(data)]
    result = subprocess.run(cmd, capture_output=True, text=True)
    if result.returncode != 0:
        print('STDERR:', result.stderr, file=sys.stderr)
        raise RuntimeError(f'curl failed: {result.returncode}')
    try:
        return json.loads(result.stdout)
    except json.JSONDecodeError:
        print('Failed to decode JSON:', result.stdout, file=sys.stderr)
        raise

def get_head_sha():
    ref = gh_api('GET', f'repos/{OWNER}/{REPO}/git/refs/heads/{BRANCH}')
    return ref['object']['sha']

def get_commit_tree_sha(commit_sha):
    commit = gh_api('GET', f'repos/{OWNER}/{REPO}/git/commits/{commit_sha}')
    return commit['tree']['sha']

def create_blob(path):
    content = Path(path).read_bytes()
    b64 = base64.b64encode(content).decode('ascii')
    payload = {'content': b64, 'encoding': 'base64'}
    blob = gh_api('POST', f'repos/{OWNER}/{REPO}/git/blobs', payload)
    return blob['sha']

def create_tree(base_tree_sha, file_blobs):
    tree = []
    for path, blob_sha in file_blobs.items():
        tree.append({'path': path, 'mode': '100644', 'type': 'blob', 'sha': blob_sha})
    payload = {'base_tree': base_tree_sha, 'tree': tree}
    new_tree = gh_api('POST', f'repos/{OWNER}/{REPO}/git/trees', payload)
    return new_tree['sha']

def create_commit(parent_sha, tree_sha, message):
    payload = {'message': message, 'parents': [parent_sha], 'tree': tree_sha}
    commit = gh_api('POST', f'repos/{OWNER}/{REPO}/git/commits', payload)
    return commit['sha']

def patch_ref(commit_sha):
    payload = {'sha': commit_sha}
    ref = gh_api('PATCH', f'repos/{OWNER}/{REPO}/git/refs/heads/{BRANCH}', payload)
    return ref

def main():
    head_sha = get_head_sha()
    print(f'HEAD: {head_sha}')
    base_tree_sha = get_commit_tree_sha(head_sha)
    print(f'Base tree: {base_tree_sha}')
    file_blobs = {}
    for f in FILES:
        blob_sha = create_blob(f)
        file_blobs[f] = blob_sha
        print(f'Blob {f}: {blob_sha}')
    new_tree_sha = create_tree(base_tree_sha, file_blobs)
    print(f'New tree: {new_tree_sha}')
    new_commit_sha = create_commit(head_sha, new_tree_sha, COMMIT_MESSAGE)
    print(f'New commit: {new_commit_sha}')
    patch_ref(new_commit_sha)
    print(f'Patched {BRANCH} to {new_commit_sha}')

if __name__ == '__main__':
    main()

